const toast = document.getElementById('toast');
let toastTimer;

function showToast(message) {
  toast.textContent = message;
    toast.classList.add('visible');
      clearTimeout(toastTimer);
        toastTimer = setTimeout(() => toast.classList.remove('visible'), 2200);
        }

        function toggleLike(button) {
          const count = button.closest('.post-card').querySelector('.likes-count');
            const liked = button.classList.toggle('liked');
              button.textContent = liked ? '♥' : '♡';
                const current = Number(count.dataset.count || count.textContent.match(/[\d.]+/)[0].replace('.', ''));
                  const updated = current + (liked ? 1 : -1);
                    count.dataset.count = updated;
                      count.textContent = `${updated.toLocaleString('pt-BR')} curtidas`;
                      }

                      function bindPostFeatures(root = document) {
                        root.querySelectorAll('.like-button:not([data-bound])').forEach((button) => {
                            button.dataset.bound = 'true';
                                button.addEventListener('click', () => toggleLike(button));
                                  });
                                    root.querySelectorAll('.save-button:not([data-bound])').forEach((button) => {
                                        button.dataset.bound = 'true';
                                            button.addEventListener('click', () => {
                                                  const saved = button.classList.toggle('saved');
                                                        button.textContent = saved ? '▣' : '♧';
                                                              showToast(saved ? 'Publicação salva' : 'Publicação removida dos salvos');
                                                                  });
                                                                    });
                                                                      root.querySelectorAll('.comment-focus:not([data-bound])').forEach((button) => {
                                                                          button.dataset.bound = 'true';
                                                                              button.addEventListener('click', () => button.closest('.post-card').querySelector('input').focus());
                                                                                });
                                                                                  root.querySelectorAll('.share-button:not([data-bound])').forEach((button) => {
                                                                                      button.dataset.bound = 'true';
                                                                                          button.addEventListener('click', () => showToast('Link da publicação copiado'));
                                                                                            });
                                                                                              root.querySelectorAll('.post-photo:not([data-bound])').forEach((photo) => {
                                                                                                  photo.dataset.bound = 'true';
                                                                                                      photo.addEventListener('dblclick', () => {
                                                                                                            const button = photo.closest('.post-card').querySelector('.like-button');
                                                                                                                  if (!button.classList.contains('liked')) toggleLike(button);
                                                                                                                        photo.classList.remove('show-heart');
                                                                                                                              void photo.offsetWidth;
                                                                                                                                    photo.classList.add('show-heart');
                                                                                                                                        });
                                                                                                                                          });
                                                                                                                                            root.querySelectorAll('.comment-form:not([data-bound])').forEach((form) => {
                                                                                                                                                form.dataset.bound = 'true';
                                                                                                                                                    const input = form.querySelector('input');
                                                                                                                                                        const publishButton = form.querySelector('.publish-comment');
                                                                                                                                                            input.addEventListener('input', () => publishButton.classList.toggle('ready', input.value.trim().length > 0));
                                                                                                                                                                form.querySelector('.emoji-button').addEventListener('click', () => {
                                                                                                                                                                      input.value += ' 😊';
                                                                                                                                                                            input.dispatchEvent(new Event('input'));
                                                                                                                                                                                  input.focus();
                                                                                                                                                                                      });
                                                                                                                                                                                          form.addEventListener('submit', (event) => {
                                                                                                                                                                                                event.preventDefault();
                                                                                                                                                                                                      const text = input.value.trim();
                                                                                                                                                                                                            if (!text) return;
                                                                                                                                                                                                                  const entry = document.createElement('p');
                                                                                                                                                                                                                        entry.className = 'comment-entry';
                                                                                                                                                                                                                              const username = document.createElement('strong');
                                                                                                                                                                                                                                    username.textContent = 'marianasilva ';
                                                                                                                                                                                                                                          entry.append(username, document.createTextNode(text));
                                                                                                                                                                                                                                                form.closest('.post-card').querySelector('.comment-list').append(entry);
                                                                                                                                                                                                                                                      input.value = '';
                                                                                                                                                                                                                                                            publishButton.classList.remove('ready');
                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                    root.querySelectorAll('.comments-link:not([data-bound])').forEach((button) => {
                                                                                                                                                                                                                                                                        button.dataset.bound = 'true';
                                                                                                                                                                                                                                                                            button.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                  const list = button.closest('.post-card').querySelector('.comment-list');
                                                                                                                                                                                                                                                                                        list.classList.toggle('comments-expanded');
                                                                                                                                                                                                                                                                                              button.textContent = list.classList.contains('comments-expanded') ? 'Ocultar comentários' : 'Ver comentários';
                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                    bindPostFeatures();

                                                                                                                                                                                                                                                                                                    function openFeatureModal(title, content) {
                                                                                                                                                                                                                                                                                                      document.querySelector('.feature-modal')?.remove();
                                                                                                                                                                                                                                                                                                        const overlay = document.createElement('div');
                                                                                                                                                                                                                                                                                                          overlay.className = 'feature-modal';
                                                                                                                                                                                                                                                                                                            overlay.innerHTML = `<section class="feature-dialog" role="dialog" aria-modal="true" aria-label="${title}"><header><strong>${title}</strong><button class="feature-close" aria-label="Fechar">×</button></header><div class="feature-content"></div></section>`;
                                                                                                                                                                                                                                                                                                              overlay.querySelector('.feature-content').append(content);
                                                                                                                                                                                                                                                                                                                document.body.append(overlay);
                                                                                                                                                                                                                                                                                                                  overlay.querySelector('.feature-close').addEventListener('click', () => overlay.remove());
                                                                                                                                                                                                                                                                                                                    overlay.addEventListener('click', (event) => { if (event.target === overlay) overlay.remove(); });
                                                                                                                                                                                                                                                                                                                      overlay.querySelector('input, textarea')?.focus();
                                                                                                                                                                                                                                                                                                                        return overlay;
                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                        function createPostCard(text) {
                                                                                                                                                                                                                                                                                                                          const card = document.createElement('article');
                                                                                                                                                                                                                                                                                                                            card.className = 'post-card';
                                                                                                                                                                                                                                                                                                                              card.dataset.post = `new-${Date.now()}`;
                                                                                                                                                                                                                                                                                                                                card.innerHTML = `<header class="post-header"><span class="avatar avatar-you">M</span><div class="post-user"><strong>marianasilva</strong><span>Agora mesmo</span></div><button class="more-icon" aria-label="Mais opções">•••</button></header><div class="post-photo new-post-photo" role="img" aria-label="Nova publicação"><span class="new-post-message"></span><span class="heart-pop">♥</span></div><div class="post-actions"><div class="action-left"><button class="action-button like-button" aria-label="Curtir">♡</button><button class="action-button comment-focus" aria-label="Comentar">▱</button><button class="action-button share-button" aria-label="Compartilhar">➤</button></div><button class="action-button save-button" aria-label="Salvar">♧</button></div><div class="post-copy"><strong class="likes-count" data-count="0">0 curtidas</strong><p><strong>marianasilva</strong> <span class="new-post-caption"></span></p><button class="comments-link">Ver comentários</button><div class="comment-list"></div><time>AGORA</time></div><form class="comment-form"><button type="button" class="emoji-button" aria-label="Adicionar emoji">☺</button><input aria-label="Adicionar comentário" placeholder="Adicione um comentário..." /><button class="publish-comment" type="submit">Publicar</button></form>`;
                                                                                                                                                                                                                                                                                                                                  card.querySelector('.new-post-message').textContent = text;
                                                                                                                                                                                                                                                                                                                                    card.querySelector('.new-post-caption').textContent = text;
                                                                                                                                                                                                                                                                                                                                      document.querySelector('.feed-column').prepend(card);
                                                                                                                                                                                                                                                                                                                                        bindPostFeatures(card);
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                        function openComposer() {
                                                                                                                                                                                                                                                                                                                                          const form = document.createElement('form');
                                                                                                                                                                                                                                                                                                                                            form.className = 'composer-form';
                                                                                                                                                                                                                                                                                                                                              form.innerHTML = '<textarea maxlength="220" placeholder="O que você quer compartilhar?" aria-label="Texto da publicação" required></textarea><button class="composer-submit" type="submit">Compartilhar</button>';
                                                                                                                                                                                                                                                                                                                                                const modal = openFeatureModal('Criar nova publicação', form);
                                                                                                                                                                                                                                                                                                                                                  form.addEventListener('submit', (event) => {
                                                                                                                                                                                                                                                                                                                                                      event.preventDefault();
                                                                                                                                                                                                                                                                                                                                                          const text = form.querySelector('textarea').value.trim();
                                                                                                                                                                                                                                                                                                                                                              if (!text) return;
                                                                                                                                                                                                                                                                                                                                                                  modal.remove();
                                                                                                                                                                                                                                                                                                                                                                      createPostCard(text);
                                                                                                                                                                                                                                                                                                                                                                          showToast('Sua publicação foi compartilhada');
                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                            function openSearch() {
                                                                                                                                                                                                                                                                                                                                                                              const content = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                content.className = 'search-content';
                                                                                                                                                                                                                                                                                                                                                                                  content.innerHTML = '<input type="search" placeholder="Buscar pessoas ou publicações" aria-label="Buscar"><div class="search-results"></div>';
                                                                                                                                                                                                                                                                                                                                                                                    const modal = openFeatureModal('Pesquisar', content);
                                                                                                                                                                                                                                                                                                                                                                                      const input = content.querySelector('input');
                                                                                                                                                                                                                                                                                                                                                                                        const results = content.querySelector('.search-results');
                                                                                                                                                                                                                                                                                                                                                                                          const accounts = ['juliana.m', 'pedro.costa', 'marina.luz', 'rafael.png', 'biaferreira', 'gui.viagens', 'marianasilva'];
                                                                                                                                                                                                                                                                                                                                                                                            const renderResults = () => {
                                                                                                                                                                                                                                                                                                                                                                                                const query = input.value.trim().toLowerCase();
                                                                                                                                                                                                                                                                                                                                                                                                    results.replaceChildren();
                                                                                                                                                                                                                                                                                                                                                                                                        accounts.filter((name) => name.includes(query)).forEach((name) => {
                                                                                                                                                                                                                                                                                                                                                                                                              const row = document.createElement('button');
                                                                                                                                                                                                                                                                                                                                                                                                                    row.className = 'search-result';
                                                                                                                                                                                                                                                                                                                                                                                                                          row.textContent = `◎  ${name}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                row.addEventListener('click', () => { modal.remove(); showToast(`Perfil de ${name}`); });
                                                                                                                                                                                                                                                                                                                                                                                                                                      results.append(row);
                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!results.children.length) results.textContent = 'Nenhum resultado encontrado.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                  input.addEventListener('input', renderResults);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderResults();
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    const storyButtons = [...document.querySelectorAll('.story')];
                                                                                                                                                                                                                                                                                                                                                                                                                                                    let currentStory = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    function showStory(index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                      currentStory = (index + storyButtons.length) % storyButtons.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const button = storyButtons[currentStory];
                                                                                                                                                                                                                                                                                                                                                                                                                                                          const modal = document.getElementById('story-modal');
                                                                                                                                                                                                                                                                                                                                                                                                                                                            modal.querySelector('.story-modal-user strong').textContent = button.dataset.story;
                                                                                                                                                                                                                                                                                                                                                                                                                                                              modal.querySelector('.story-modal-user .avatar').className = `avatar ${button.querySelector('.avatar').classList[1]}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                modal.classList.add('open');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  modal.setAttribute('aria-hidden', 'false');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const progress = modal.querySelector('.story-progress span');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      progress.style.animation = 'none';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        void progress.offsetWidth;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          progress.style.animation = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          storyButtons.forEach((button, index) => button.addEventListener('click', () => showStory(index)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function closeStory() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const modal = document.getElementById('story-modal');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              modal.classList.remove('open');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                modal.setAttribute('aria-hidden', 'true');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelector('.close-story').addEventListener('click', closeStory);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelector('.story-next').addEventListener('click', () => showStory(currentStory + 1));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById('story-modal').addEventListener('click', (event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (event.target.id === 'story-modal') closeStory();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.querySelectorAll('[data-label]').forEach((button) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    button.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const label = button.dataset.label;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (label === 'Pesquisar') openSearch();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (label === 'Criar') openComposer();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (label === 'Notificações') showToast('Você está em dia com as notificações');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (label !== 'Mais opções') showToast(`${label} — demonstração`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.addEventListener('keydown', (event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (event.key === 'Escape') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                closeStory();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.querySelector('.feature-modal')?.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.querySelectorAll('.bottom-nav button').forEach((button) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const label = button.getAttribute('aria-label');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (label === 'Criar') openComposer();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (label === 'Início') window.scrollTo({ top: 0, behavior: 'smooth' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else showToast(`${label} — demonstração`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.querySelectorAll('.text-button').forEach((button) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (button.textContent.trim() === 'Seguir') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      button.textContent = 'Seguindo';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.style.color = '#262626';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else if (button.textContent.trim() === 'Seguindo') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      button.textContent = 'Seguir';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            button.style.color = '#0095f6';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else showToast('Perfil atualizado');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  